// Every op belonging to a leaf under `id`, sorted along the commit-index axis -- the aggregate a
// collapsed subsystem row shows in place of its hidden per-feature detail.
function descendantOps(id) {
  const out = [];
  const stack = [id];
  while (stack.length) {
    const node = byId(stack.pop());
    if (!node) continue;
    if (node.children && node.children.length) {
      for (const c of node.children) stack.push(c);
    } else {
      const ops = layout.opsByFeature[node.id];
      if (ops) out.push(...ops);
    }
  }
  out.sort((a, b) => a.commit_index - b.commit_index);
  return out;
}

