"""The Composition Workbench's dependency-graph layout contract.

`computeGraphLayout` in `editor/vscode/media/workbench.js` is a pure function (no DOM/color), so
we slice it out and exercise it under node -- the same harness style as `test_map_layout.py`. It
lays features out as a temporally-layered co-change graph: x = temporal rank (median op commit),
node magnitude = op count, y = barycenter crossing-min with subsystem cohesion, and a `frontier`
that filters ops so scrubbing accretes the graph.
"""

from __future__ import annotations

import json
import pathlib
import shutil
import subprocess

import pytest

_JS = pathlib.Path(__file__).resolve().parents[1] / "editor/vscode/media/workbench.js"


def _run(map_view: dict, history: dict | None = None, opts: dict | None = None) -> dict:
    node = shutil.which("node")
    if node is None:
        pytest.skip("node not available")
    text = _JS.read_text(encoding="utf-8")
    start = text.index("function computeGraphLayout")
    end = text.index("// ---- end-graph-layout")
    snippet = text[start:end]
    harness = snippet + (
        f"const m = {json.dumps(map_view)};\n"
        f"const h = {json.dumps(history or {'commits': [], 'ops': []})};\n"
        f"const L = computeGraphLayout(m, h, {json.dumps(opts or {})});\n"
        "console.log(JSON.stringify(L));\n"
    )
    res = subprocess.run([node, "-e", harness], capture_output=True, text=True)
    assert res.returncode == 0, res.stderr
    return json.loads(res.stdout)


def _node(id_, parent, children, kind="feature"):
    return {"id": id_, "parent": parent, "children": children, "label": id_, "kind": kind,
            "size": 1, "op_count": 0, "dir": f"src/{id_}/"}


def _ops(*specs):
    return {"commits": [{"index": i} for i in range(200)],
            "ops": [{"id": f"o{i}", "kind": "add", "feature_id": f, "commit_index": c}
                    for i, (f, c) in enumerate(specs)]}


def test_only_features_with_ops_are_placed():
    m = {"roots": ["A", "B", "C"],
         "nodes": [_node("A", None, []), _node("B", None, []), _node("C", None, [])],
         "edges": []}
    # C has no ops -> it does not exist on the graph.
    out = _run(m, _ops(("A", 0), ("A", 1), ("B", 5)))
    ids = {n["id"] for n in out["nodes"]}
    assert ids == {"A", "B"}


def test_op_count_is_node_magnitude():
    m = {"roots": ["A"], "nodes": [_node("A", None, [])], "edges": []}
    out = _run(m, _ops(("A", 0), ("A", 1), ("A", 3)))
    assert out["nodeById"]["A"]["opCount"] == 3


def test_layers_are_monotonic_in_temporal_rank():
    # Five features, each concentrated at a different commit -> five distinct temporal ranks, so
    # later-median features never land in an earlier layer than earlier-median ones.
    m = {"roots": [c for c in "ABCDE"],
         "nodes": [_node(c, None, []) for c in "ABCDE"], "edges": []}
    out = _run(m, _ops(("A", 0), ("B", 10), ("C", 20), ("D", 30), ("E", 40)))
    layer_of = {n["id"]: n["layer"] for n in out["nodes"]}
    order = ["A", "B", "C", "D", "E"]
    for earlier, later in zip(order, order[1:]):
        assert layer_of[earlier] <= layer_of[later]
    # layer commit ranges are non-decreasing
    los = [lyr["commitLo"] for lyr in out["layers"] if lyr["commitLo"] is not None]
    assert los == sorted(los)


def test_collapsed_subsystem_is_one_meta_node_rolling_up_descendant_ops():
    m = {"roots": ["N0"],
         "nodes": [_node("N0", None, ["F1", "F2"], kind="subsystem"),
                   _node("F1", "N0", []), _node("F2", "N0", [])],
         "edges": []}
    out = _run(m, _ops(("F1", 0), ("F1", 1), ("F2", 2)), opts={"collapsed": ["N0"]})
    assert len(out["nodes"]) == 1
    meta = out["nodes"][0]
    assert meta["id"] == "N0" and meta["isMeta"] is True
    assert meta["opCount"] == 3  # 2 from F1 + 1 from F2


def test_frontier_filters_ops_so_scrubbing_accretes():
    m = {"roots": ["A", "B"], "nodes": [_node("A", None, []), _node("B", None, [])], "edges": []}
    hist = _ops(("A", 0), ("A", 2), ("B", 50))
    early = _run(m, hist, opts={"frontier": 10})
    assert {n["id"] for n in early["nodes"]} == {"A"}  # B's op is past the frontier
    later = _run(m, hist, opts={"frontier": 100})
    assert {n["id"] for n in later["nodes"]} == {"A", "B"}


def test_edge_into_collapsed_subsystem_reroutes_and_self_loops_drop():
    m = {"roots": ["N0", "F3"],
         "nodes": [_node("N0", None, ["F1", "F2"], kind="subsystem"),
                   _node("F1", "N0", []), _node("F2", "N0", []), _node("F3", None, [])],
         "edges": [{"a": "F1", "b": "F3", "weight": 2.0},   # reroutes to N0<->F3
                   {"a": "F1", "b": "F2", "weight": 9.0}]}   # both under N0 -> self-loop, dropped
    out = _run(m, _ops(("F1", 0), ("F2", 1), ("F3", 2)), opts={"collapsed": ["N0"]})
    assert out["edges"] == [{"a": "F3", "b": "N0", "weight": 2.0}]


def test_topk_edges_kept_rest_in_overflow():
    nodes = [_node("hub", None, [])] + [_node(f"l{i}", None, []) for i in range(5)]
    edges = [{"a": "hub", "b": f"l{i}", "weight": float(5 - i)} for i in range(5)]
    m = {"roots": ["hub"] + [f"l{i}" for i in range(5)], "nodes": nodes, "edges": edges}
    hist = _ops(*[("hub", 0)] + [(f"l{i}", i + 1) for i in range(5)])
    out = _run(m, hist, opts={"topK": 3})
    assert out["overflow"]["hub"] == 2  # the two lightest of hub's 5 edges are counted, not lost


def test_deterministic_across_runs():
    m = {"roots": [c for c in "ABCDEF"],
         "nodes": [_node(c, None, []) for c in "ABCDEF"],
         "edges": [{"a": "A", "b": "C", "weight": 3.0}, {"a": "B", "b": "D", "weight": 2.0}]}
    hist = _ops(("A", 0), ("B", 1), ("C", 10), ("D", 11), ("E", 20), ("F", 21))
    a = _run(m, hist)
    b = _run(m, hist)
    key = lambda o: [(n["id"], n["layer"], n["order"]) for n in o["nodes"]]
    assert key(a) == key(b)


def test_empty_map_is_empty_graph():
    out = _run({"roots": [], "nodes": [], "edges": []})
    assert out["nodes"] == [] and out["edges"] == []

