// ─── The dependency graph ───────────────────────────────────────────────────────────────────
// Fills the pane; scrolls only when the node count genuinely overflows. Geometry is derived from
// the layout's logical (layer, order) grid + the pane width, so a resize reflows continuously
// (the ResizeObserver re-runs render()).
const GRAPH = { mx: 96, my: 44, colMin: 156, rowGap: 78, rMin: 7, rMax: 26, axisH: 40 };
let graphView = null; // { geom, handleEl, frontierEl } -- set each render for the frontier scrubber

function graphGeom() {
  const cols = Math.max(1, layout.cols);
  const rows = Math.max(1, layout.rows);
  const paneW = Math.max(rail.clientWidth || 0, 360);
  const colW = Math.max(GRAPH.colMin, (paneW - GRAPH.mx * 2) / cols);
  const w = Math.round(GRAPH.mx * 2 + cols * colW);
  const h = Math.round(GRAPH.my * 2 + rows * GRAPH.rowGap + GRAPH.axisH);
  const perLayer = {};
  for (const nd of layout.nodes) perLayer[nd.layer] = (perLayer[nd.layer] || 0) + 1;
  const maxOps = Math.max(1, ...layout.nodes.map((nd) => nd.opCount));
  const bandY = GRAPH.my + (rows * GRAPH.rowGap) / 2;
  return {
    cols, rows, colW, w, h, maxCommit: Math.max(0, layout.commitCount - 1),
    cx: (layer) => GRAPH.mx + layer * colW + colW / 2,
    cy: (nd) => bandY + (nd.order - ((perLayer[nd.layer] || 1) - 1) / 2) * GRAPH.rowGap,
    rOf: (nd) => GRAPH.rMin + (GRAPH.rMax - GRAPH.rMin) * Math.sqrt(nd.opCount / maxOps),
    scrubX: (idx) => GRAPH.mx + (idx / Math.max(1, Math.max(0, layout.commitCount - 1))) * (w - GRAPH.mx * 2),
    xToCommit: (x) => Math.max(0, Math.min(layout.commitCount - 1,
      Math.round(((x - GRAPH.mx) / Math.max(1, w - GRAPH.mx * 2)) * Math.max(1, layout.commitCount - 1)))),
  };
}

function nodeColor(nd) {
  const n = byId(nd.id);
  return (n && n.color) || "#8a8a8a"; // meta/subsystem nodes have no identity hue -> neutral
}

function beyondFrontier(nd) {
  return playheadCommitIndex != null && nd.medianCommit > playheadCommitIndex;
}

function renderGraph() {
  const prevScroll = rail.scrollTop;
  rail.innerHTML = "";
  const geom = graphGeom();
  const svg = mk("svg", { width: geom.w, height: geom.h, class: "railsvg graphsvg" });
  const bandLayer = mk("g", { class: "bands" });
  const edgeLayer = mk("g", { class: "edges" });
  const nodeLayer = mk("g", { class: "gnodes" });
  svg.appendChild(bandLayer);
  svg.appendChild(edgeLayer);
  svg.appendChild(nodeLayer);

  renderSubsystemBands(bandLayer, geom);
  renderGraphEdges(edgeLayer, geom);
  for (const nd of layout.nodes) nodeLayer.appendChild(renderGraphNode(nd, geom));
  renderTimeAxis(svg, geom);

  rail.appendChild(svg);
  rail.scrollTop = prevScroll;
}

// Subsystem bands: a soft rounded envelope behind the (≥2) nodes of one subsystem, so a cluster
// reads as a region. Clicking the band's label re-collapses the subsystem to its meta-node.
function renderSubsystemBands(layer, geom) {
  const bySub = {};
  for (const nd of layout.nodes) {
    if (nd.isMeta || !nd.subsystem) continue;
    (bySub[nd.subsystem] || (bySub[nd.subsystem] = [])).push(nd);
  }
  for (const sub in bySub) {
    const members = bySub[sub];
    if (members.length < 2) continue;
    const xs = members.map((m) => geom.cx(m.layer));
    const ys = members.map((m) => geom.cy(m));
    const rmax = Math.max(...members.map(geom.rOf));
    const x1 = Math.min(...xs) - rmax - 14, x2 = Math.max(...xs) + rmax + 14;
    const y1 = Math.min(...ys) - rmax - 22, y2 = Math.max(...ys) + rmax + 14;
    const subNode = byId(sub);
    const rect = mk("rect", {
      x: x1, y: y1, width: x2 - x1, height: y2 - y1, rx: 14, class: "subsystem-band",
    });
    layer.appendChild(rect);
    const label = mk("text", { x: x1 + 10, y: y1 + 15, class: "subsystem-band-label" });
    label.textContent = (subNode && subNode.label) || sub;
    label.addEventListener("click", () => toggleCollapse(sub)); // re-cluster this subsystem
    layer.appendChild(label);
  }
}

function renderGraphEdges(layer, geom) {
  const maxW = Math.max(1, ...layout.edges.map((e) => e.weight));
  for (const e of layout.edges) {
    const a = layout.nodeById[e.a], b = layout.nodeById[e.b];
    if (!a || !b) continue;
    const x1 = geom.cx(a.layer), y1 = geom.cy(a);
    const x2 = geom.cx(b.layer), y2 = geom.cy(b);
    const dim = beyondFrontier(a) || beyondFrontier(b);
    let d;
    if (a.layer === b.layer) {
