      const bow = 26 + Math.abs(y2 - y1) * 0.2;
      d = `M ${x1} ${y1} C ${x1 + bow} ${y1}, ${x2 + bow} ${y2}, ${x2} ${y2}`;
    } else {
      const mx = (x1 + x2) / 2;
      d = `M ${x1} ${y1} C ${mx} ${y1}, ${mx} ${y2}, ${x2} ${y2}`;
    }
    const path = mk("path", {
      d, class: "gedge" + (dim ? " beyond" : ""), "data-a": e.a, "data-b": e.b,
    });
    path.setAttribute("stroke-width", (0.6 + 2.4 * (e.weight / maxW)).toFixed(2));
