  const color = nodeColor(nd);
  const g = mk("g", {
    class: "gnode" + (nd.id === state.selected ? " selected" : "") + (beyondFrontier(nd) ? " beyond" : ""),
    transform: `translate(${x}, ${y})`, "data-id": nd.id, "data-med": nd.medianCommit,
  });
