"""The dependency-graph layout + terminal renderer, shared by `sgt graph` (static print) and the
Textual TUI.

This is the terminal counterpart of the VS Code workbench's `computeGraphLayout` (a faithful port,
kept behaviour-parallel on purpose). A commit-index is not a snapshot node -- it's a *set of ops*
spread across features -- so we don't draw a commit spine. We lay out the FEATURES:

    x  (layer)  = temporal rank: a feature's generation, from the median commit-index of its ops
                  (foundations first, recent work last), coarsened into a few columns so a
                  2000-op commit is just *where a node sits*, never a wall of glyphs.
    magnitude   = op count (a big feature reads as a long bar, not an unreadable smear).
    y  (order)  = barycenter crossing-minimization over the (undirected) co-change edges, with a
                  subsystem-cohesion constraint so a subsystem's features stay a contiguous band.
    frontier    = a fold point: only ops with commit_index <= frontier count, so scrubbing accretes.

The terminal render is the honest projection of that model onto a scrollable column: generations
top-to-bottom, features within each as an identity-colored row with a magnitude bar and its
strongest co-change links -- everything a user needs to answer "what is here, how big, when, what
it connects to, and what can I edit."
"""

from __future__ import annotations

from .color import color_for

# ── Layout (pure) ────────────────────────────────────────────────────────────────────────────────


def graph_layout(
    map_view: dict,
    history_view: dict,
    *,
    collapsed=(),
    frontier: int | None = None,
    top_k: int = 4,
    target_per_layer: int = 4,
    max_layers: int = 9,
) -> dict:
    collapsed = set(collapsed)
    fr = float("inf") if frontier is None else frontier
    by_id = {n["id"]: n for n in map_view.get("nodes", [])}

    ops_by_feature: dict[str, list] = {}
    for op in history_view.get("ops", []):
        fid = op.get("feature_id")
        if fid is None or op["commit_index"] > fr:
            continue
        ops_by_feature.setdefault(fid, []).append(op)
    for fid in ops_by_feature:
        ops_by_feature[fid].sort(key=lambda o: o["commit_index"])

    def nearest_subsystem(node_id: str):
        cur = by_id[node_id].get("parent") if node_id in by_id else None
        while cur is not None:
            p = by_id.get(cur)
            if p and p.get("kind") == "subsystem":
                return cur
            cur = p.get("parent") if p else None
        return None

    def leaves_under(node_id: str) -> list[str]:
        out, stack = [], [node_id]
        while stack:
            node = by_id.get(stack.pop())
            if not node:
                continue
            children = node.get("children") or []
            if children:
                stack.extend(children)
            else:
                out.append(node["id"])
        return out

    # Visible node set: a collapsed subsystem becomes one meta-node (subtree hidden); an expanded
    # subsystem is a grouping band only; a feature is always a node.
    visible = []

    def visit(node_id: str):
        node = by_id.get(node_id)
        if not node:
            return
        is_sub = node.get("kind") == "subsystem"
        if is_sub and node_id not in collapsed:
            for c in node.get("children") or []:
                visit(c)
            return
        is_meta = is_sub
        leaves = leaves_under(node_id) if is_meta else [node_id]
        visible.append({
            "id": node_id, "is_meta": is_meta, "leaves": leaves,
            "subsystem": node_id if is_meta else nearest_subsystem(node_id),
        })

    for r in sorted(map_view.get("roots") or []):
        visit(r)

    # Aggregate op count + temporal rank (median op commit) over each node's leaves; drop empties.
    placed = []
    for v in visible:
        cis = [op["commit_index"] for leaf in v["leaves"] for op in ops_by_feature.get(leaf, [])]
        if not cis:
            continue
        cis.sort()
        placed.append({
            **v, "op_count": len(cis), "median_commit": cis[(len(cis) - 1) // 2],
            "first_commit": cis[0], "last_commit": cis[-1],
        })

    # Layer (x): rank by median commit, bucket into L equal-count layers (monotonic + evenly filled).
    placed.sort(key=lambda p: (p["median_commit"], p["id"]))
    n = len(placed)
    L = max(1, min(max_layers, -(-n // target_per_layer)))  # ceil(n / target_per_layer)
    for rank, p in enumerate(placed):
        p["layer"] = 0 if n <= 1 else min(L - 1, (rank * L) // n)
    layers = []
    for i in range(L):
        meds = [m["median_commit"] for m in placed if m["layer"] == i]
        layers.append({
            "index": i, "count": len(meds),
            "commit_lo": min(meds) if meds else None,
            "commit_hi": max(meds) if meds else None,
        })

    # Visible co-change edges: reroute to visible endpoints, drop self-loops, merge, top-K per node.
    id_to_visible = {leaf: p["id"] for p in placed for leaf in p["leaves"]}
    placed_ids = {p["id"] for p in placed}

    def resolve_visible(node_id: str):
        if node_id in id_to_visible:
            return id_to_visible[node_id]
        cur = node_id
        while cur is not None and cur not in placed_ids:
            cur = by_id.get(cur, {}).get("parent")
        return cur

    merged: dict[tuple, float] = {}
    for e in map_view.get("edges", []):
        a, b = resolve_visible(e["a"]), resolve_visible(e["b"])
        if a is None or b is None or a == b:
            continue
        key = (a, b) if a < b else (b, a)
        merged[key] = merged.get(key, 0.0) + (e.get("weight") or 0.0)
    all_edges = [{"a": k[0], "b": k[1], "weight": w} for k, w in merged.items()]
    all_edges.sort(key=lambda e: (-e["weight"], e["a"] + e["b"]))
    per_node: dict[str, int] = {}
    edges, overflow = [], {}
    for e in all_edges:
        ca, cb = per_node.get(e["a"], 0), per_node.get(e["b"], 0)
        if ca < top_k and cb < top_k:
            edges.append(e)
            per_node[e["a"]] = ca + 1
            per_node[e["b"]] = cb + 1
        else:
            overflow[e["a"]] = overflow.get(e["a"], 0) + 1
            overflow[e["b"]] = overflow.get(e["b"], 0) + 1

    # Order (y) within layers: barycenter crossing-min with subsystem cohesion (blocks move together).
    adj: dict[str, list] = {p["id"]: [] for p in placed}
    for e in edges:
        adj[e["a"]].append(e["b"])
        adj[e["b"]].append(e["a"])
    in_layer = [[] for _ in range(L)]
    for p in placed:
        in_layer[p["layer"]].append(p)
    for layer in in_layer:
        layer.sort(key=lambda p: ((p["subsystem"] or ""), p["median_commit"], p["id"]))
        for i, p in enumerate(layer):
            p["order"] = i
    pos = {p["id"]: p["order"] for p in placed}
    for _ in range(6):
        for layer in in_layer:
            if len(layer) < 2:
                continue
            for p in layer:
                ns = adj[p["id"]]
                p["_bary"] = (sum(pos.get(q, 0) for q in ns) / len(ns)) if ns else p["order"]
            blocks: dict[str, list] = {}
            for p in layer:
                blocks.setdefault(p["subsystem"] or p["id"], []).append(p)
            blist = [{"k": k, "members": m, "bary": sum(x["_bary"] for x in m) / len(m)}
                     for k, m in blocks.items()]
            blist.sort(key=lambda b: (b["bary"], b["k"]))
            idx = 0
            for blk in blist:
                blk["members"].sort(key=lambda p: (p["_bary"], p["id"]))
                for p in blk["members"]:
                    p["order"] = idx
                    idx += 1
        pos = {p["id"]: p["order"] for p in placed}

    return {
        "nodes": placed, "edges": edges, "overflow": overflow, "layers": layers,
        "node_by_id": {p["id"]: p for p in placed}, "ops_by_feature": ops_by_feature,
        "cols": L, "rows": max([1] + [len(l) for l in in_layer]),
        "commit_count": len(history_view.get("commits") or []),
    }


# ── Terminal render ────────────────────────────────────────────────────────────────────────────


def _rgb(hex_str: str) -> tuple[int, int, int]:
    h = hex_str.lstrip("#")
    return int(h[0:2], 16), int(h[2:4], 16), int(h[4:6], 16)


def _fg(hex_str: str, s: str) -> str:
    r, g, b = _rgb(hex_str)
    return f"\x1b[38;2;{r};{g};{b}m{s}\x1b[0m"


_DIM = "\x1b[2m"
_BOLD = "\x1b[1m"
_RESET = "\x1b[0m"


def _bar(op_count: int, max_ops: int, width: int) -> tuple[int, int]:
    """(filled, total) block widths -- sqrt so area, not linear length, carries magnitude (a huge
    op-set doesn't blow past the pane; a tiny one still shows)."""
    if max_ops <= 0:
        return 0, width
    frac = (op_count / max_ops) ** 0.5
    return max(1, round(frac * width)), width


def render_graph_lines(
    map_view: dict,
    history_view: dict,
    *,
    selected: str | None = None,
    frontier: int | None = None,
    collapsed=(),
    color: bool = True,
    bar_width: int = 16,
    label_width: int = 26,
    neighbors: int = 2,
) -> list[str]:
    """Render the graph as a list of terminal lines (ANSI truecolor when `color`). Generations run
    top-to-bottom; each feature is one row: identity glyph, label, magnitude bar, op count, and its
    strongest co-change links -- the terminal projection of the same model the VS Code graph draws."""
    layout = graph_layout(map_view, history_view, collapsed=collapsed, frontier=frontier)
    labels = {n["id"]: n.get("label", n["id"]) for n in map_view.get("nodes", [])}

    def paint(hex_str: str, s: str) -> str:
        return _fg(hex_str, s) if color else s

    def dim(s: str) -> str:
        return f"{_DIM}{s}{_RESET}" if color else s

    def bold(s: str) -> str:
        return f"{_BOLD}{s}{_RESET}" if color else s

    # Co-change neighbours per node (strongest first) for the "connects to" annotation.
    nbrs: dict[str, list] = {}
    for e in sorted(layout["edges"], key=lambda e: -e["weight"]):
        nbrs.setdefault(e["a"], []).append(e["b"])
        nbrs.setdefault(e["b"], []).append(e["a"])

    max_ops = max([1] + [n["op_count"] for n in layout["nodes"]])
    lines: list[str] = []

    total_ops = sum(n["op_count"] for n in layout["nodes"])
    lines.append(bold(f" {len(layout['nodes'])} feature(s)  ·  {layout['commit_count']} commit(s)  ·  {total_ops} op(s)"))
    if frontier is not None:
        lines.append(dim(f"   frontier: folded at commit {frontier} (later features hidden)"))
    lines.append("")

    for layer in layout["layers"]:
        members = sorted((n for n in layout["nodes"] if n["layer"] == layer["index"]),
                         key=lambda n: n["order"])
        if not members:
            continue
        lo, hi = layer["commit_lo"], layer["commit_hi"]
        span = f"commit {lo}" if lo == hi else f"commits {lo}–{hi}"
        lines.append(dim(f" ── gen {layer['index']} · {span} " + "─" * max(2, 46 - len(span))))
        for nd in members:
            fid = nd["id"]
            hexc = color_for(fid)
            is_sel = fid == selected
            glyph = "◈" if nd["is_meta"] else "●"
            marker = "▸ " if is_sel else "  "
            label = labels.get(fid, fid)
            if nd["is_meta"]:
                label = f"{label} ({len(nd['leaves'])} features)"
            label = label[:label_width].ljust(label_width)
            filled, total = _bar(nd["op_count"], max_ops, bar_width)
            bar = paint(hexc, "█" * filled) + dim("·" * (total - filled))
            count = str(nd["op_count"]).rjust(5)
            link_ids = nbrs.get(fid, [])[:neighbors]
            links = ", ".join(labels.get(x, x) for x in link_ids)
            extra = len(nbrs.get(fid, [])) - len(link_ids)
            if links:
                links = "↔ " + links + (f" +{extra}" if extra > 0 else "")
            row = f" {marker}{paint(hexc, glyph)} {bold(label) if is_sel else label}  {bar} {dim(count)}"
            if links:
                row += "  " + dim(links)
            lines.append(row)
        lines.append("")
    return lines

def _cmd_map(args) -> int:
    return _map(".", args.as_json, args.rebuild)


def _cmd_graph(args) -> int:
    return _graph(".", frontier=args.at, color=not args.no_color)

