let pending: NodeJS.Timeout | undefined;
const refresh = () => {
  clearTimeout(pending);
  pending = setTimeout(() => {
    // A `sgt map`/`compose` READ rebuilds and rewrites tree.json/ideal.json/label_cache.json/...
    // under `.sgt/`, which trips this very watcher. Invalidating on our own writes re-issues the
    // read -> infinite rebuild loop (the sidebar spinning forever). Skip while our subprocess is
    // active; external mutations arrive while we're idle, and our own mutations invalidate
    // explicitly, so neither is missed.
    if (store.sgt.recentlyActive()) return;
    store.invalidate();
  }, 250); // debounce write storms
};

edits.old:
// ---- graph-layout (test slice boundary) ----
// The dependency-graph layout. A commit-index is NOT a snapshot node -- it's a set of ops spread
// across features -- so we don't draw a commit spine. We draw the FEATURES (the durable "what")
// as a temporally-layered co-change graph:
//   x (layer) = temporal rank: a feature sits in the generation of its median op's commit-index,
//               so foundations fall left and recent work right, but coarsened into ~N columns so a
//               2000-op commit is just *where nodes sit*, never a wall of glyphs.
//   node area = op count -- a huge op-set reads as a big node instead of an unreadable smear.
//   y (order) = barycenter crossing-minimization over the (undirected) co-change edges, with a
//               subsystem-cohesion constraint so a subsystem's features stay a contiguous band.
//   frontier  = a fold point: only ops with commit_index <= frontier count, so scrubbing accretes
//               the graph (nodes grow / appear) rather than marching a snapshot pointer.
// Pure (no DOM/color): sliced out and exercised under node (tests/test_graph_layout.py).
function computeGraphLayout(map, history, opts) {
  opts = opts || {};
  const collapsed = new Set(opts.collapsed || []);
  const frontier = opts.frontier == null ? Infinity : opts.frontier;
  const topK = opts.topK || 4;
  const targetPerLayer = opts.targetPerLayer || 4;
  const maxLayers = opts.maxLayers || 9;

  const byId = {};
  for (const n of map.nodes || []) byId[n.id] = n;

  // Ops per feature, filtered to the frontier -- the magnitude + temporal signal for each leaf.
  const opsByFeature = {};
  for (const op of (history && history.ops) || []) {
    if (op.feature_id == null || op.commit_index > frontier) continue;
    (opsByFeature[op.feature_id] || (opsByFeature[op.feature_id] = [])).push(op);
  }
  for (const fid in opsByFeature) opsByFeature[fid].sort((a, b) => a.commit_index - b.commit_index);

  // Visible nodes: DFS the tree; a collapsed subsystem becomes ONE meta-node (its subtree hidden),
  // an expanded subsystem is a grouping band only (never a node), a feature is always a node. Each
  // node carries `subsystem` = its nearest subsystem ancestor id, for the cohesion constraint and
  // banding. `leaves` on a meta-node = the features it rolls up (for op/commit aggregation).
  const visible = [];
  function nearestSubsystem(id) {
    let cur = byId[id] ? byId[id].parent : null;
    while (cur != null) {
      const p = byId[cur];
      if (p && p.kind === "subsystem") return cur;
      cur = p ? p.parent : null;
    }
    return null;
  }
  function leavesUnder(id) {
    const out = [];
    const stack = [id];
    while (stack.length) {
      const node = byId[stack.pop()];
      if (!node) continue;
      if (node.children && node.children.length) for (const c of node.children) stack.push(c);
      else out.push(node.id);
    }
    return out;
  }
  function visit(id) {
    const node = byId[id];
    if (!node) return;
    const isSub = node.kind === "subsystem";
    if (isSub && !collapsed.has(id)) {
      for (const c of node.children || []) visit(c);
      return;
    }
    const isMeta = isSub; // a visible subsystem here is necessarily collapsed
    const leaves = isMeta ? leavesUnder(id) : [id];
    visible.push({ id, isMeta, leaves, subsystem: isMeta ? id : nearestSubsystem(id) });
  }
  for (const r of (map.roots || []).slice().sort()) visit(r);

  // Aggregate op count + temporal rank (median op commit-index) over each node's leaves. Nodes
  // with no ops at this frontier don't exist yet -- dropped, so scrubbing left empties the graph.
  const placed = [];
  for (const v of visible) {
    const cis = [];
    for (const leaf of v.leaves) for (const op of opsByFeature[leaf] || []) cis.push(op.commit_index);
    if (!cis.length) continue;
    cis.sort((a, b) => a - b);
    const median = cis[Math.floor((cis.length - 1) / 2)];
    placed.push({ ...v, opCount: cis.length, medianCommit: median, firstCommit: cis[0], lastCommit: cis[cis.length - 1] });
  }

  // Layer (x): rank by median commit, bucket into L equal-count layers -> monotonic in time and
  // evenly filled despite the heavy per-commit skew. Deterministic tie-break by id.
  placed.sort((a, b) => a.medianCommit - b.medianCommit || (a.id < b.id ? -1 : 1));
  const n = placed.length;
  const L = Math.max(1, Math.min(maxLayers, Math.ceil(n / targetPerLayer)));
  placed.forEach((p, rank) => {
    p.layer = n <= 1 ? 0 : Math.min(L - 1, Math.floor((rank * L) / n));
  });
  const layers = [];
  for (let i = 0; i < L; i++) {
    const members = placed.filter((p) => p.layer === i);
    // Range over the members' temporal RANK (median commit), not their first/last op -- a feature's
    // ops can span the whole history, so first/last would make every layer's range overlap; the
    // median is what the layer axis actually orders on, so it stays monotonic across layers.
    layers.push({
      index: i,
      count: members.length,
      commitLo: members.length ? Math.min(...members.map((m) => m.medianCommit)) : null,
      commitHi: members.length ? Math.max(...members.map((m) => m.medianCommit)) : null,
    });
  }

  // Visible co-change edges: reroute each endpoint up to its nearest visible node, drop self-loops,
  // merge parallels (sum weight), keep top-K per node by weight (rest counted in overflow).
  const idToVisible = {};
  for (const p of placed) for (const leaf of p.leaves) idToVisible[leaf] = p.id;
  const placedIds = new Set(placed.map((p) => p.id));
  function resolveVisible(id) {
    if (idToVisible[id]) return idToVisible[id];
    let cur = id;
    while (cur != null && !placedIds.has(cur)) cur = byId[cur] ? byId[cur].parent : null;
    return cur;
  }
  const merged = {};
  for (const e of map.edges || []) {
    const a = resolveVisible(e.a);
    const b = resolveVisible(e.b);
    if (a == null || b == null || a === b) continue;
    const key = a < b ? `${a} ${b}` : `${b} ${a}`;
    merged[key] = (merged[key] || 0) + (e.weight || 0);
  }
  let allEdges = Object.keys(merged).map((k) => {
    const [a, b] = k.split(" ");
    return { a, b, weight: merged[k] };
  });
  allEdges.sort((x, y) => y.weight - x.weight || (x.a + x.b < y.a + y.b ? -1 : 1));
  const perNode = {};
  const edges = [];
  const overflow = {};
  for (const e of allEdges) {
    const ca = perNode[e.a] || 0, cb = perNode[e.b] || 0;
    if (ca < topK && cb < topK) {
      edges.push(e);
      perNode[e.a] = ca + 1;
      perNode[e.b] = cb + 1;
    } else {
      overflow[e.a] = (overflow[e.a] || 0) + 1;
      overflow[e.b] = (overflow[e.b] || 0) + 1;
    }
  }

  // Order (y) within each layer: barycenter crossing-minimization over co-change neighbors, with a
  // subsystem-cohesion constraint (a subsystem's nodes move together as a block, so clusters read
  // as bands). Deterministic: fixed sweep count, stable initial order, id tie-break.
  const adj = {};
  for (const p of placed) adj[p.id] = [];
  for (const e of edges) {
    adj[e.a].push(e.b);
    adj[e.b].push(e.a);
  }
  const inLayer = [];
  for (let i = 0; i < L; i++) inLayer.push([]);
  placed.forEach((p) => inLayer[p.layer].push(p));
  // stable initial order: subsystem block, then time, then id
  for (const layer of inLayer) {
    layer.sort((a, b) =>
      (a.subsystem || "").localeCompare(b.subsystem || "") ||
      a.medianCommit - b.medianCommit ||
      (a.id < b.id ? -1 : 1)
    );
    layer.forEach((p, i) => (p.order = i));
  }
  const posById = {};
  const syncPos = () => { for (const p of placed) posById[p.id] = p.order; };
  syncPos();
  for (let sweep = 0; sweep < 6; sweep++) {
    for (const layer of inLayer) {
      if (layer.length < 2) continue;
      // node barycenter = mean order of its neighbors (any layer); isolated nodes keep their slot.
      for (const p of layer) {
        const ns = adj[p.id];
        p._bary = ns.length ? ns.reduce((s, q) => s + (posById[q] || 0), 0) / ns.length : p.order;
      }
      // block barycenter = mean of member barycenters; order blocks, then nodes within block.
      const blocks = {};
      for (const p of layer) (blocks[p.subsystem || p.id] || (blocks[p.subsystem || p.id] = [])).push(p);
      const blockList = Object.keys(blocks).map((k) => {
        const members = blocks[k];
        return { k, members, bary: members.reduce((s, m) => s + m._bary, 0) / members.length };
      });
      blockList.sort((x, y) => x.bary - y.bary || (x.k < y.k ? -1 : 1));
      let idx = 0;
      for (const blk of blockList) {
        blk.members.sort((a, b) => a._bary - b._bary || (a.id < b.id ? -1 : 1));
        for (const p of blk.members) p.order = idx++;
      }
    }
    syncPos();
  }

  const rows = Math.max(1, ...inLayer.map((l) => l.length));
  const nodeById = {};
  for (const p of placed) nodeById[p.id] = p;
  return { nodes: placed, edges, overflow, layers, nodeById, opsByFeature, cols: L, rows,
    commitCount: ((history && history.commits) || []).length };
}
// ---- end-graph-layout (test slice boundary) ----

