def test_render_frontier_note_present_when_folded():
    m = {"roots": ["A"], "nodes": [_node("A", None, [])], "edges": []}
    lines = render_graph_lines(m, _hist(("A", 0), ("A", 5)), frontier=3, color=False)
    assert any("frontier" in ln for ln in lines)


