    assert eps[0]["op_ids"] == ["o0", "o1"] and eps[0]["op_count"] == 2
    assert eps[0]["sha"] == "sha0" and eps[0]["subject"] == "add login"
    assert eps[0]["kinds"] == {"add": 1, "extend": 1}
    assert eps[1]["op_ids"] == ["o2"] and eps[1]["kinds"] == {"rework": 1}


