// Chunk-car packing: allocate a lane's pixel width across its cars, width ∝ log2(op_count) on
// top of a shared floor -- a fat chapter reads visibly wider, but no car is ever so narrow it
// disappears or stops being a clickable/hoverable target. Degrades to (near-)equal slivers once
// there are more cars than the floor alone fits. Mirrors sgt/tui/graph.py's _pack_car_widths,
// kept behaviour-parallel (pixels here, terminal columns there).
function packCarWidths(opCounts, totalWidth, minWidth) {
  const n = opCounts.length;
  if (!n || totalWidth <= 0) return opCounts.map(() => 0);
  const gap = 2; // visual seam between adjacent cars
  const usable = Math.max(0, totalWidth - gap * (n - 1));
  if (n * minWidth >= usable) {
    const base = Math.floor(usable / n);
    const widths = opCounts.map(() => base);
    const order = opCounts.map((_, i) => i).sort((a, b) => opCounts[b] - opCounts[a]);
    let extra = usable - base * n;
    for (let k = 0; k < extra; k++) widths[order[k % n]] += 1;
    return widths;
  }
  const weights = opCounts.map((c) => Math.log2(c + 1) + 1);
  const totalW = weights.reduce((a, b) => a + b, 0) || 1;
  const budget = usable - n * minWidth;
  const widths = weights.map((w) => minWidth + Math.floor(budget * (w / totalW)));
  const leftover = usable - widths.reduce((a, b) => a + b, 0);
  if (leftover > 0) {
    const maxI = opCounts.reduce((best, c, i) => (c > opCounts[best] ? i : best), 0);
    widths[maxI] += leftover;
  }
  return widths;
}

