    if proc.returncode != 0:
        return {}
    out: dict[str, set[str]] = {}
    for record in proc.stdout.split("\x1e"):
        record = record.strip("\n")
        if not record or "\x1f" not in record:
            continue
        sha, body = record.split("\x1f", 1)
        out[sha.strip()] = set(parse_op_ids(body))
    return out

