"""RGA (Replicated Growable Array) — the sequence CRDT LiveHub documents are built on.

A document is a sequence of elements (characters or lines). Every element is identified by the
``actor@lamport`` of the :class:`~livehub.op.Op` that created it, so two replicas that have seen
the same ops agree on element identity. An insert names the element it follows (its ``left``
anchor); a delete tombstones an element by id but keeps it in place so later inserts that
anchored on it still resolve. Applying the same set of ops in *any* order converges to the same
visible sequence — that convergence is the whole point, and it is what lets many actors edit one
document in a live room with no locking and no lost writes.
"""

from __future__ import annotations

from dataclasses import dataclass

from livehub.op import Op, OpKind


def elem_id(op: Op) -> str:
    """The stable element id an insert op creates: its causal ``actor@lamport``. Unique across
    replicas because each actor advances its own Lamport clock monotonically."""
    return f"{op.actor}@{op.lamport}"


def _precedence(eid: str) -> tuple[int, str]:
    """Total order over element ids for tie-breaking concurrent inserts at the same anchor:
    higher Lamport wins, ties broken by actor id. Total (no two ids compare equal) so the
    resulting sequence is identical on every replica regardless of op arrival order."""
    actor, lamport = eid.rsplit("@", 1)
    return (int(lamport), actor)


@dataclass
class Element:
    """One position in the sequence. Tombstoned elements are retained (``deleted=True``) rather
    than removed so that ids anchoring on them stay resolvable — removing them would break the
    convergence guarantee for a concurrent insert that named a since-deleted left anchor."""

    id: str
    value: str
    left: str | None
    deleted: bool = False


class RGA:
    """A replicated growable array. ``apply`` folds an op into local state idempotently (applying
    the same op twice is a no-op); ``value`` materializes the visible (non-tombstoned) sequence."""

    def __init__(self) -> None:
        self._elements: list[Element] = []
        self._applied: set[str] = set()  # op ids already folded in — idempotency guard
        self._index: dict[str, int] = {}  # element id -> position in _elements

    def apply(self, op: Op) -> None:
        if op.id in self._applied:
            return  # idempotent: a re-delivered op changes nothing
        self._applied.add(op.id)
        if op.kind is OpKind.INSERT:
            self._insert(Element(id=elem_id(op), value=op.payload["value"], left=op.payload.get("left")))
        elif op.kind is OpKind.DELETE:
            self._delete(op.payload["elem_id"])

    def _rebuild_index(self) -> None:
        self._index = {e.id: i for i, e in enumerate(self._elements)}

    def _insert(self, elem: Element) -> None:
        if elem.id in self._index:
            return  # element already present (op re-delivered under a different op id)
        # Start just past the left anchor (or at the head for a leading insert), then skip over any
        # elements that were concurrently inserted into the same region and outrank this one by
        # precedence. Stopping at the first lower-precedence element is what makes concurrent
        # inserts land in the same total order on every replica.
        start = 0 if elem.left is None else self._index.get(elem.left, len(self._elements) - 1) + 1
        idx = start
        while idx < len(self._elements) and _precedence(self._elements[idx].id) > _precedence(elem.id):
            idx += 1
        self._elements.insert(idx, elem)
        self._rebuild_index()

    def _delete(self, target: str) -> None:
        pos = self._index.get(target)
        if pos is not None:
            self._elements[pos].deleted = True

    def value(self) -> str:
        return "".join(e.value for e in self._elements if not e.deleted)

    def elements(self) -> list[Element]:
        """Every element including tombstones, in sequence order — the view the analysis layer
        needs (a since-deleted symbol is still evidence of intent)."""
        return list(self._elements)

