"""Program analysis over a converged document — the layer that makes LiveHub *not* plain CRDT.

A sequence CRDT guarantees every replica converges on the same source. It says nothing about
whether that source makes *sense*: two actors can each make a locally-fine edit that, once merged,
leaves the code semantically broken. The canonical case — one actor writes ``foo()`` that calls
``bar``, another deletes ``def bar`` — merges cleanly to a text where ``foo`` references a symbol
that no longer exists. That is a **dangling reference**: a real defect, but not a merge failure.

This module is the detector. It reads a document's materialized source (``Document.text()``) and
answers three questions, all as pure functions of the text:

* :func:`defined_symbols` — what module-level symbols does this source define?
* :func:`dependency_graph` — which defined symbols reference which others (intra-module edges)?
* :func:`dangling_references` — which *calls* resolve to nothing that exists here?

:func:`conflict` (the next layer) turns a dangling reference into first-class converged state that
a room carries until it is resolved, rather than rejecting the merge that produced it.

Scope of v1, kept deliberately small and honest:
  * Analysis is **per top-level def/class**. Loose module-level statements are not yet scoped as a
    referrer (they rarely occur in these docs); noted, not silently handled.
  * A "dangling" reference is a *called* name (``ast.Call`` on a bare ``ast.Name``) that is not a
    local binding, parameter, import, Python builtin, or top-level definition. Restricting to calls
    is the clearest signal for the collaboration scenario and avoids guessing at bare-name uses.
  * Local bindings are collected conservatively across a symbol's whole subtree (every
    ``Store``-context name, parameter, nested def/class, import). Conservative means we err toward
    *not* flagging — a false "dangling" is worse than a missed one when the report drives conflicts.
  * A source that does not parse yields empty results: a syntactic collision is a different conflict
    class, surfaced elsewhere, not something this semantic layer can reason about.
"""

from __future__ import annotations

import ast
import builtins
from dataclasses import dataclass

_BUILTINS = frozenset(dir(builtins))


@dataclass(frozen=True)
class DanglingReference:
    """A call to ``target`` inside ``source`` that resolves to no definition available in the
    document. ``line`` is the 1-based line of the call in the materialized source."""

    source: str
    target: str
    line: int


def _parse(source: str) -> ast.Module | None:
    """Parse ``source``, or ``None`` if it does not parse — the signal that only a syntactic-conflict
    layer (not this one) can say anything about the merged text."""
    try:
        return ast.parse(source)
    except SyntaxError:
        return None


def _top_level(tree: ast.Module) -> list[ast.FunctionDef | ast.AsyncFunctionDef | ast.ClassDef]:
    """The module's top-level def/class nodes — the referrers this layer analyzes."""
    return [n for n in tree.body
            if isinstance(n, (ast.FunctionDef, ast.AsyncFunctionDef, ast.ClassDef))]


def _imported_names(tree: ast.Module) -> set[str]:
    """Every name a module-level import binds (``import x`` -> ``x``, ``from y import z as w`` -> the
    bound alias) — names that resolve outside the document and so are never dangling."""
    names: set[str] = set()
    for node in ast.walk(tree):
        if isinstance(node, ast.Import):
            for alias in node.names:
                names.add((alias.asname or alias.name).split(".", 1)[0])
        elif isinstance(node, ast.ImportFrom):
            for alias in node.names:
                names.add(alias.asname or alias.name)
    return names


def _local_bindings(node: ast.AST) -> set[str]:
    """Every name bound anywhere in ``node``'s subtree: parameters, ``Store``-context names (assign
    / for / with-as / comprehension targets / walrus), nested def & class names, and any import.
    Conservative on purpose — anything bound here is *not* a dangling call, so over-collecting only
    suppresses false positives."""
    bound: set[str] = set()
    for inner in ast.walk(node):
        if isinstance(inner, (ast.FunctionDef, ast.AsyncFunctionDef)):
            args = inner.args
            for a in (*args.posonlyargs, *args.args, *args.kwonlyargs):
                bound.add(a.arg)
            if args.vararg:
                bound.add(args.vararg.arg)
            if args.kwarg:
                bound.add(args.kwarg.arg)
            bound.add(inner.name)
        elif isinstance(inner, ast.ClassDef):
            bound.add(inner.name)
        elif isinstance(inner, ast.Name) and isinstance(inner.ctx, ast.Store):
            bound.add(inner.id)
        elif isinstance(inner, ast.ExceptHandler) and inner.name:
            bound.add(inner.name)
        elif isinstance(inner, ast.Import):
            for alias in inner.names:
                bound.add((alias.asname or alias.name).split(".", 1)[0])
        elif isinstance(inner, ast.ImportFrom):
            for alias in inner.names:
                bound.add(alias.asname or alias.name)
    return bound


def _called_names(node: ast.AST) -> list[tuple[str, int]]:
    """Every ``(name, line)`` where a bare ``ast.Name`` is the callee of a call in ``node`` — the
    references whose target must resolve to something, or be dangling."""
    return [(n.func.id, n.func.lineno)
            for n in ast.walk(node)
            if isinstance(n, ast.Call) and isinstance(n.func, ast.Name)]


def defined_symbols(source: str) -> set[str]:
    """The module-level symbols ``source`` defines (top-level def/class names). Empty if the source
    does not parse."""
    tree = _parse(source)
    if tree is None:
        return set()
    return {n.name for n in _top_level(tree)}


def dependency_graph(source: str) -> dict[str, set[str]]:
    """Each defined symbol -> the set of *other* defined symbols it references by name (a call, base
    class, or any load of a top-level name). Intra-module edges only — the graph whose broken edges
    :func:`dangling_references` reports. Empty if the source does not parse.

    Every defined symbol appears as a key (a symbol that references nothing maps to an empty set), so
    callers can treat the keyset as the node set."""
    tree = _parse(source)
    if tree is None:
        return {}
    defined = {n.name for n in _top_level(tree)}
    graph: dict[str, set[str]] = {}
    for sym in _top_level(tree):
        refs = {n.id for n in ast.walk(sym)
                if isinstance(n, ast.Name) and isinstance(n.ctx, ast.Load) and n.id in defined}
        refs.discard(sym.name)  # a symbol referencing itself (recursion) is not a dependency edge
        graph[sym.name] = refs
    return graph


def dangling_references(source: str) -> list[DanglingReference]:
    """Every call, inside a defined symbol, to a name that resolves to nothing available in the
    document — not a local binding/parameter, not an import, not a Python builtin, not a top-level
    definition. This is the semantic defect a concurrent delete-vs-use merge produces. Sorted by
    ``(line, source, target)`` for a deterministic report. Empty if the source does not parse."""
    tree = _parse(source)
    if tree is None:
        return []
    defined = {n.name for n in _top_level(tree)}
    imported = _imported_names(tree)
    dangling: list[DanglingReference] = []
    for sym in _top_level(tree):
        bound = _local_bindings(sym)
        for name, line in _called_names(sym):
            if name in defined or name in imported or name in bound or name in _BUILTINS:
                continue
            dangling.append(DanglingReference(source=sym.name, target=name, line=line))
    dangling.sort(key=lambda d: (d.line, d.source, d.target))
    return dangling

