/* In-situ save preview: a dashed, translucent "ghost car" at the frontier showing the work that
   would land on the next `sgt save`. Dashed + low-opacity (family with .gcar-thematic / .gbar-plan)
   reads as anticipated, not yet real; a slow pulse marks it live. Not a click target. */
.gcar-pending {
  fill-opacity: 0.18;
  stroke: var(--accent);
  stroke-width: 1.4px;
  stroke-dasharray: 3 3;
  cursor: default;
  animation: gcar-pending-pulse 1.8s ease-in-out infinite;
}

.gcar-pending-count {
  fill: var(--accent);
  font-size: 9px;
  text-anchor: middle;
  pointer-events: none;
  font-variant-numeric: tabular-nums;
  font-weight: 600;
  paint-order: stroke;
  stroke: var(--bg);
  stroke-width: 2.5px;
  stroke-linejoin: round;
}

@keyframes gcar-pending-pulse {
  0%, 100% { fill-opacity: 0.14; }
  50% { fill-opacity: 0.30; }
}

/* The ghost just landed (a save committed it into a real checkpoint): the newest car enters once
   from the ghost look into a solid car. A one-shot keyframe -- not a transition -- because
   renderGraph rebuilds the car DOM each render, so there's no persistent element to interpolate. */
.gcar-landing {
  animation: gcar-land 340ms ease-out;
}

@keyframes gcar-land {
  from { fill-opacity: 0.18; stroke: var(--accent); stroke-dasharray: 3 3; }
  to { fill-opacity: 0.55; stroke: var(--bg); stroke-dasharray: 0; }
}

