def _sample(seq: list, k: int) -> list:
    """`k` roughly-evenly-spaced elements of `seq`, always including the first and last (dedup'd)."""
    if k >= len(seq):
        return list(seq)
    step = (len(seq) - 1) / (k - 1)
    idxs = sorted({round(i * step) for i in range(k)})
    return [seq[i] for i in idxs]


